	size_t x4 = srcStep + 4;
	size_t y1 = 0;
	size_t y2 = 1;
	size_t y3 = dstStep[0];
	size_t y4 = dstStep[0] + 1;
	UINT32 max_x = roi->width - 1;

	size_t y = 0;
	for (size_t i = 0; y < roi->height - roi->height % 2; y += 2, i++)
	{
		const BYTE* src = pSrc + y * srcStep;
		BYTE* ydst = pDst[0] + y * dstStep[0];
		BYTE* udst = pDst[1] + i * dstStep[1];
		BYTE* vdst = pDst[2] + i * dstStep[2];

		for (size_t x = 0; x < roi->width; x += 2)
		{
			BYTE R = 0;
			BYTE G = 0;
			BYTE B = 0;
			INT32 Ra = 0;
			INT32 Ga = 0;
			INT32 Ba = 0;
			/* row 1, pixel 1 */
			Ba = B = *(src + x1 + 0);
			Ga = G = *(src + x1 + 1);
			Ra = R = *(src + x1 + 2);
			ydst[y1] = RGB2Y(R, G, B);

			if (x < max_x)
			{
				/* row 1, pixel 2 */
				Ba += B = *(src + x2 + 0);
				Ga += G = *(src + x2 + 1);
				Ra += R = *(src + x2 + 2);
				ydst[y2] = RGB2Y(R, G, B);
			}

