static BOOL freerdp_client_rdp_file_set_integer(rdpFile* file, const char* name, long value)
{
	DWORD* targetValue = nullptr;
	rdpFileLine* line = nullptr;
#ifdef DEBUG_CLIENT_FILE
	WLog_DBG(TAG, "%s:i:%ld", name, value);
#endif

	if (value < 0)
		return FALSE;

	if (!freerdp_client_rdp_file_find_integer_entry(file, name, &targetValue, &line))
	{
		SSIZE_T index = freerdp_client_rdp_file_add_line(file);
		if (index == -1)
			return FALSE;
		line = &file->lines[index];
	}

	if (targetValue)
	{
		*targetValue = (DWORD)value;
		return TRUE;
	}

	if (line)
	{
		free(line->name);
		line->name = _strdup(name);
		if (!line->name)
		{
			free(line->name);
			line->name = nullptr;
			return FALSE;
		}

		line->iValue = value;
		line->flags = RDP_FILE_LINE_FLAG_FORMATTED;
		line->flags |= RDP_FILE_LINE_FLAG_TYPE_INTEGER;
		line->valueLength = 0;
		return TRUE;
	}

	return FALSE;
}

static BOOL freerdp_client_parse_rdp_file_integer(rdpFile* file, const char* name,
                                                  const char* value)
{
	char* endptr = nullptr;
	long ivalue = 0;
	errno = 0;
	ivalue = strtol(value, &endptr, 0);

	if ((endptr == nullptr) || (errno != 0) || (endptr == value) || (ivalue > INT32_MAX) ||
	    (ivalue < INT32_MIN))
	{
		if (file->flags & RDP_FILE_FLAG_PARSE_INT_RELAXED)
		{
			WLog_WARN(TAG, "Integer option %s has invalid value %s, using default", name, value);
			return TRUE;
		}
		else
		{
			WLog_ERR(TAG, "Failed to convert RDP file integer option %s [value=%s]", name, value);
			return FALSE;
		}
	}

	return freerdp_client_rdp_file_set_integer(file, name, ivalue);
}

static BOOL freerdp_client_rdp_file_set_string(rdpFile* file, const char* name, const char* value)
{
	LPSTR* targetValue = nullptr;
	rdpFileLine* line = nullptr;
#ifdef DEBUG_CLIENT_FILE
	WLog_DBG(TAG, "%s:s:%s", name, value);
#endif

	if (!name || !value)
		return FALSE;

	if (!freerdp_client_rdp_file_find_string_entry(file, name, &targetValue, &line))
	{
		SSIZE_T index = freerdp_client_rdp_file_add_line(file);
		if (index == -1)
			return FALSE;
		line = &file->lines[index];
	}

	if (targetValue)
	{
		if ((uintptr_t)(*targetValue) != UINTPTR_MAX)
			free(*targetValue);

		*targetValue = _strdup(value);
		return ((*targetValue) != nullptr);
	}

	if (line)
	{
		free(line->name);
		free(line->sValue);
		line->name = _strdup(name);
		line->sValue = _strdup(value);
		if (!line->name || !line->sValue)
		{
			free(line->name);
			free(line->sValue);
			line->name = nullptr;
			line->sValue = nullptr;
			return FALSE;
		}

		line->flags = RDP_FILE_LINE_FLAG_FORMATTED;
		line->flags |= RDP_FILE_LINE_FLAG_TYPE_STRING;
		line->valueLength = 0;
		return TRUE;
	}

	return FALSE;
}

static SSIZE_T freerdp_client_rdp_file_add_line(rdpFile* file)
{
	SSIZE_T index = (SSIZE_T)file->lineCount;

	while ((file->lineCount + 1) > file->lineSize)
	{
		size_t new_size = file->lineCount + 2048;
		rdpFileLine* new_line = (rdpFileLine*)realloc(file->lines, new_size * sizeof(rdpFileLine));

		if (!new_line)
			return -1;

		file->lines = new_line;
		file->lineSize = new_size;
	}

	ZeroMemory(&(file->lines[file->lineCount]), sizeof(rdpFileLine));
	file->lines[file->lineCount].index = (size_t)index;
	(file->lineCount)++;
	return index;
}

static BOOL trim(char** strptr)
{
	char* start = nullptr;
	char* str = nullptr;
	char* end = nullptr;

	start = str = *strptr;
	if (!str)
		return TRUE;
	if (!(~((size_t)str)))
		return TRUE;
	end = str + strlen(str) - 1;

	while (isspace(*str))
		str++;

	while ((end > str) && isspace(*end))
		end--;
	end[1] = '\0';
	if (start == str)
		*strptr = str;
	else
	{
		*strptr = _strdup(str);
		free(start);
		return *strptr != nullptr;
	}

	return TRUE;
}

static BOOL parse_line(rdpFile* file, char* line, size_t length, rdp_file_fkt_parse parse)
{
	if (length <= 1)
		return TRUE;

	const char* beg = line;
#if !defined(WITHOUT_FREERDP_3x_DEPRECATED)
#if defined(WITH_EMBEDDED_CLI_IN_RDP_FILES)
	if (beg[0] == '/')
	{
		freerdp_warn_deprecated(WLog_Get(TAG), "Parsing CLI options within an RDP file",
		                        "Will be removed in FreeRDP 4.0");
		if (!freerdp_client_add_option(file, line))
			return FALSE;

		return TRUE; /* FreeRDP option */
	}
#endif
#endif

	char* d1 = strchr(line, ':');

	if (!d1)
		return TRUE; /* not first delimiter */

	const char* type = &d1[1];
	char* d2 = strchr(type, ':');

	if (!d2)
		return TRUE; /* no second delimiter */

	if ((d2 - d1) != 2)
		return TRUE; /* improper type length */

	*d1 = 0;
	*d2 = 0;
	const char* name = beg;
	const char* value = &d2[1];

	if (parse && parse(file->context, name, *type, value))
		return TRUE;

	if (*type == 'i')
	{
		/* integer type */
		return freerdp_client_parse_rdp_file_integer(file, name, value);
	}
	if (*type == 's')
	{
		/* string type */
		return freerdp_client_rdp_file_set_string(file, name, value);
	}
	if (*type == 'b')
	{
		/* binary type */
		WLog_ERR(TAG, "Unsupported RDP file binary option %s [value=%s]", name, value);
	}

	return TRUE;
}

BOOL freerdp_client_parse_rdp_file_buffer_ex(rdpFile* file, const BYTE* buffer, size_t size,
                                             rdp_file_fkt_parse parse)
{
	BOOL rc = FALSE;
	char* copy = nullptr;

	if (!file)
		return FALSE;
	if (size < 2)
		return FALSE;

	if ((buffer[0] == BOM_UTF16_LE[0]) && (buffer[1] == BOM_UTF16_LE[1]))
	{
		LPCWSTR uc = (LPCWSTR)(&buffer[2]);
		const size_t charlen = size / sizeof(WCHAR) - 1;
		copy = ConvertWCharNToUtf8Alloc(uc, charlen, &size);
		if (!copy)
		{
			WLog_ERR(TAG, "Failed to convert RDP file from UCS2 to UTF8");
			return FALSE;
		}
	}
	else
	{
		copy = calloc(1, size + sizeof(BYTE));

		if (!copy)
			return FALSE;

		memcpy(copy, buffer, size);
	}

	char* context = nullptr;
	char* line = strtok_s(copy, "\r\n", &context);

	while (line)
	{
		const size_t length = strnlen(line, size);

		if (!parse_line(file, line, length, parse))
			goto fail;

		line = strtok_s(nullptr, "\r\n", &context);
	}

	rc = trim_strings(file);
fail:
	free(copy);
	return rc;
}

BOOL freerdp_client_parse_rdp_file_ex(rdpFile* file, const char* name, rdp_file_fkt_parse parse)
{
	BOOL status = 0;
	BYTE* buffer = nullptr;
	FILE* fp = nullptr;
	size_t read_size = 0;
	INT64 file_size = 0;
	const char* fname = name;

	if (!file || !name)
		return FALSE;

	if (_strnicmp(fname, "file://", 7) == 0)
		fname = &name[7];

	fp = winpr_fopen(fname, "r");
	if (!fp)
	{
		WLog_ERR(TAG, "Failed to open RDP file %s", name);
		return FALSE;
	}

	if (_fseeki64(fp, 0, SEEK_END) < 0)
		goto fail;
	file_size = _ftelli64(fp);
	if (_fseeki64(fp, 0, SEEK_SET) < 0)
		goto fail;

	if (file_size < 1)
	{
		WLog_ERR(TAG, "RDP file %s is empty", name);
		goto fail;
	}

	buffer = (BYTE*)malloc((size_t)file_size + 2);

	if (!buffer)
		goto fail;

	read_size = fread(buffer, (size_t)file_size, 1, fp);

	if (!read_size)
	{
		if (!ferror(fp))
			read_size = (size_t)file_size;
	}

	if (read_size < 1)
	{
		WLog_ERR(TAG, "Could not read from RDP file %s", name);
		goto fail;
	}

	buffer[file_size] = '\0';
	buffer[file_size + 1] = '\0';
	status = freerdp_client_parse_rdp_file_buffer_ex(file, buffer, (size_t)file_size, parse);

fail:
	(void)fclose(fp);
	free(buffer);
	return status;
}

static inline void freerdp_client_file_string_reset(char** target)
{
	WINPR_ASSERT(target);
	freerdp_client_file_string_check_free(*target);
	*target = (char*)UINTPTR_MAX;
}

static inline BOOL FILE_POPULATE_STRING(char** _target, const rdpSettings* _settings,
                                        FreeRDP_Settings_Keys_String _option)
{
	WINPR_ASSERT(_target);
	WINPR_ASSERT(_settings);

	const char* str = freerdp_settings_get_string(_settings, _option);
	freerdp_client_file_string_reset(_target);
	if (str)
	{
		char* copy = _strdup(str);
		if (!copy)
			return FALSE;
		*_target = copy;
	}
	return TRUE;
}

static char* freerdp_client_channel_args_to_string(const rdpSettings* settings, const char* channel,
                                                   const char* option)
{
	ADDIN_ARGV* args = freerdp_dynamic_channel_collection_find(settings, channel);
	const char* filters[] = { option };
	if (!args || (args->argc < 2))
		return nullptr;

	return CommandLineToCommaSeparatedValuesEx(args->argc - 1, args->argv + 1, filters,
	                                           ARRAYSIZE(filters));
}

static BOOL rdp_opt_duplicate(const rdpSettings* _settings, FreeRDP_Settings_Keys_String _id,
                              char** _key)
{
	WINPR_ASSERT(_settings);
	WINPR_ASSERT(_key);
	const char* tmp = freerdp_settings_get_string(_settings, _id);

	if (tmp)
	{
		*_key = _strdup(tmp);
		if (!*_key)
			return FALSE;
	}

	return TRUE;
}

BOOL freerdp_client_write_rdp_file(const rdpFile* file, const char* name, BOOL unicode)
{
	int status = 0;
	WCHAR* unicodestr = nullptr;

	if (!file || !name)
		return FALSE;

	const size_t size = freerdp_client_write_rdp_file_buffer(file, nullptr, 0);
	if (size == 0)
		return FALSE;
	char* buffer = calloc(size + 1ULL, sizeof(char));
	if (!buffer)
		return FALSE;

	if (freerdp_client_write_rdp_file_buffer(file, buffer, size + 1) != size)
	{
		WLog_ERR(TAG, "freerdp_client_write_rdp_file: error writing to output buffer");
		free(buffer);
		return FALSE;
	}

	FILE* fp = winpr_fopen(name, "w+b");

	if (fp)
	{
		if (unicode)
		{
			size_t len = 0;
			unicodestr = ConvertUtf8NToWCharAlloc(buffer, size, &len);

			if (!unicodestr)
			{
				free(buffer);
				(void)fclose(fp);
				return FALSE;
			}

			/* Write multi-byte header */
			if ((fwrite(BOM_UTF16_LE, sizeof(BYTE), 2, fp) != 2) ||
			    (fwrite(unicodestr, sizeof(WCHAR), len, fp) != len))
			{
				free(buffer);
				free(unicodestr);
				(void)fclose(fp);
				return FALSE;
			}

			free(unicodestr);
		}
		else
		{
			if (fwrite(buffer, 1, size, fp) != size)
			{
				free(buffer);
				(void)fclose(fp);
				return FALSE;
			}
		}

		(void)fflush(fp);
		status = fclose(fp);
	}

	free(buffer);
	return (status == 0);
}

static SSIZE_T freerdp_client_write_setting_to_buffer(char** buffer, size_t* bufferSize,
                                                      WINPR_FORMAT_ARG const char* fmt, ...)
{
	va_list ap = WINPR_C_ARRAY_INIT;
	SSIZE_T len = 0;
	char* buf = nullptr;
	size_t bufSize = 0;

	if (!buffer || !bufferSize || !fmt)
		return -1;

	buf = *buffer;
	bufSize = *bufferSize;

	va_start(ap, fmt);
	len = vsnprintf(buf, bufSize, fmt, ap);
	va_end(ap);
	if (len < 0)
		return -1;

	/* _snprintf doesn't add the ending \0 to its return value */
	++len;

	/* we just want to know the size - return it */
	if (!buf && !bufSize)
		return len;

	if (!buf)
		return -1;

	/* update buffer size and buffer position and replace \0 with \n */
	if (bufSize >= (size_t)len)
	{
		*bufferSize -= (size_t)len;
		buf[len - 1] = '\n';
		*buffer = buf + len;
	}
	else
		return -1;

	return len;
}

static SSIZE_T write_custom_parameters(const rdpFile* file, char* buffer, size_t size)
{
	WINPR_ASSERT(file);

	SSIZE_T totalSize = 0;
	/* custom parameters */
	for (size_t i = 0; i < file->lineCount; ++i)
	{
		SSIZE_T res = -1;
		const rdpFileLine* curLine = &file->lines[i];

		if (curLine->flags & RDP_FILE_LINE_FLAG_TYPE_INTEGER)
			res = freerdp_client_write_setting_to_buffer(&buffer, &size, "%s:i:%" PRIu32,
			                                             curLine->name, (UINT32)curLine->iValue);
		else if (curLine->flags & RDP_FILE_LINE_FLAG_TYPE_STRING)
			res = freerdp_client_write_setting_to_buffer(&buffer, &size, "%s:s:%s", curLine->name,
			                                             curLine->sValue);
		if (res < 0)
			return res;

		totalSize += res;
	}
	return totalSize;
}

size_t freerdp_client_write_rdp_file_buffer(const rdpFile* file, char* buffer, size_t size)
{
	size_t totalSize = 0;

	if (!file)
		return 0;

	/* either buffer and size are null or non-null */
	if ((!buffer || !size) && (buffer || size))
		return 0;

	/* integer parameters */
	const SSIZE_T intsize = write_int_parameters(file, buffer, size);
	if (intsize < 0)
		return 0;
	totalSize += (size_t)intsize;
	if (buffer)
		buffer += intsize;

	/* string parameters */
	const SSIZE_T stringsize = write_string_parameters(file, buffer, size);
	if (stringsize < 0)
		return 0;
	totalSize += (size_t)stringsize;
	if (buffer)
		buffer += stringsize;

	/* custom parameters */
	const SSIZE_T customsize = write_custom_parameters(file, buffer, size);
	if (customsize < 0)
		return 0;
	totalSize += (size_t)customsize;
	return totalSize;
}

static ADDIN_ARGV* rdp_file_to_args(const char* channel, const char* values)
{
	size_t count = 0;
	char** p = nullptr;
	ADDIN_ARGV* args = freerdp_addin_argv_new(0, nullptr);
	if (!args)
		return nullptr;
	if (!freerdp_addin_argv_add_argument(args, channel))
		goto fail;

	p = CommandLineParseCommaSeparatedValues(values, &count);
	for (size_t x = 0; x < count; x++)
	{
		BOOL rc = 0;
		const char* val = p[x];
		const size_t len = strlen(val) + 8;
		char* str = calloc(len, sizeof(char));
		if (!str)
			goto fail;

		(void)_snprintf(str, len, "device:%s", val);
		rc = freerdp_addin_argv_add_argument(args, str);
		free(str);
		if (!rc)
			goto fail;
	}
	CommandLineParserFree(p);
	return args;

fail:
	CommandLineParserFree(p);
	freerdp_addin_argv_free(args);
	return nullptr;
}

static BOOL freerdp_apply_connection_type_from_file(const rdpFile* file, rdpSettings* settings,
                                                    UINT32 type)
{
	struct network_settings
	{
		FreeRDP_Settings_Keys_Bool id;
		BOOL apply;
		BOOL value[7];
	};
	WINPR_ASSERT(file);

	const struct network_settings config[] = { { FreeRDP_DisableWallpaper,
		                                         (~file->DisableWallpaper) == 0,
		                                         { TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE } },
		                                       { FreeRDP_AllowFontSmoothing,
		                                         (~file->AllowFontSmoothing) == 0,
		                                         { FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE } },
		                                       { FreeRDP_AllowDesktopComposition,
		                                         (~file->AllowDesktopComposition) == 0,
		                                         { FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, TRUE } },
		                                       { FreeRDP_DisableFullWindowDrag,
		                                         (~file->DisableFullWindowDrag) == 0,
		                                         { TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE } },
		                                       { FreeRDP_DisableMenuAnims,
		                                         (~file->DisableMenuAnims) == 0,
		                                         { TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, FALSE } },
		                                       { FreeRDP_DisableThemes,
		                                         (~file->DisableThemes) == 0,
		                                         { TRUE, FALSE, FALSE, FALSE, FALSE, FALSE,
		                                           FALSE } } };

	switch (type)
	{
		case CONNECTION_TYPE_INVALID:
			return TRUE;

		case CONNECTION_TYPE_MODEM:
		case CONNECTION_TYPE_BROADBAND_LOW:
		case CONNECTION_TYPE_BROADBAND_HIGH:
		case CONNECTION_TYPE_SATELLITE:
		case CONNECTION_TYPE_WAN:
		case CONNECTION_TYPE_LAN:
		case CONNECTION_TYPE_AUTODETECT:
			break;
		default:
			WLog_WARN(TAG, "Unknown ConnectionType %" PRIu32 ", aborting", type);
			return FALSE;
	}

	for (size_t x = 0; x < ARRAYSIZE(config); x++)
	{
		const struct network_settings* cur = &config[x];
		if (!cur->apply)
			continue;

		if (!freerdp_settings_set_bool(settings, cur->id, cur->value[type - 1]))
			return FALSE;
	}
	return TRUE;
}

static BOOL freerdp_set_connection_type_from_file(const rdpFile* file, rdpSettings* settings,
                                                  UINT32 type)
{
	WINPR_ASSERT(file);
	if (!freerdp_settings_set_uint32(settings, FreeRDP_ConnectionType, type))
		return FALSE;

	switch (type)
	{
		case CONNECTION_TYPE_INVALID:
		case CONNECTION_TYPE_MODEM:
		case CONNECTION_TYPE_BROADBAND_LOW:
		case CONNECTION_TYPE_SATELLITE:
		case CONNECTION_TYPE_BROADBAND_HIGH:
		case CONNECTION_TYPE_WAN:
		case CONNECTION_TYPE_LAN:
			if (!freerdp_apply_connection_type_from_file(file, settings, type))
				return FALSE;
			break;
		case CONNECTION_TYPE_AUTODETECT:
			if (!freerdp_apply_connection_type_from_file(file, settings, type))
				return FALSE;
			/* Automatically activate GFX and RFX codec support */
#ifdef WITH_GFX_H264
			if (!freerdp_settings_set_bool(settings, FreeRDP_GfxAVC444v2, TRUE) ||
			    !freerdp_settings_set_bool(settings, FreeRDP_GfxAVC444, TRUE) ||
			    !freerdp_settings_set_bool(settings, FreeRDP_GfxH264, TRUE))
				return FALSE;
#endif
			if (!freerdp_settings_set_bool(settings, FreeRDP_RemoteFxCodec, TRUE) ||
			    !freerdp_settings_set_bool(settings, FreeRDP_SupportGraphicsPipeline, TRUE))
				return FALSE;
			break;
		default:
			WLog_WARN(TAG, "Unknown ConnectionType %" PRIu32 ", aborting", type);
			return FALSE;
	}

	return TRUE;
}

BOOL freerdp_client_populate_settings_from_rdp_file(const rdpFile* file, rdpSettings* settings)
{
	if (!freerdp_client_populate_settings_from_rdp_file_unchecked(file, settings))
		return FALSE;

	DWORD type = freerdp_settings_get_uint32(settings, FreeRDP_ConnectionType);
	if ((~file->ConnectionType) == 0)
	{
		if (freerdp_settings_get_bool(settings, FreeRDP_NetworkAutoDetect))
			type = CONNECTION_TYPE_AUTODETECT;
	}
	return freerdp_set_connection_type_from_file(file, settings, type);
}

static rdpFileLine* freerdp_client_rdp_file_find_line_by_name(const rdpFile* file, const char* name)
{
	BOOL bFound = FALSE;
	rdpFileLine* line = nullptr;

	for (size_t index = 0; index < file->lineCount; index++)
	{
		line = &(file->lines[index]);

		if (line->flags & RDP_FILE_LINE_FLAG_FORMATTED)
		{
			if (_stricmp(name, line->name) == 0)
			{
				bFound = TRUE;
				break;
			}
		}
	}

	return (bFound) ? line : nullptr;
}

const char* freerdp_client_rdp_file_get_string_option(const rdpFile* file, const char* name)
{
	LPSTR* value = nullptr;
	rdpFileLine* line = nullptr;

	rdpFile* wfile = WINPR_CAST_CONST_PTR_AWAY(file, rdpFile*);
	if (freerdp_client_rdp_file_find_string_entry(wfile, name, &value, &line))
	{
		if (value && ~(size_t)(*value))
			return *value;
		if (line)
			return line->sValue;
	}

	return nullptr;
}

static inline char* error_string(char* errbuf, size_t errbuf_size, int errnum)
{
	av_strerror(errnum, errbuf, errbuf_size);
	return errbuf;
}

static const char* get_vaapi_device(void)
{
	static char device[MAX_PATH] = WINPR_C_ARRAY_INIT;
	static bool initialized = false;
	if (!initialized)
	{
		initialized = true;
		// NOLINTNEXTLINE(concurrency-mt-unsafe)
		const char* env = getenv("FREERDP_VAAPI_DEVICE");
		if (env)
			(void)_snprintf(device, sizeof(device), "%s", env);
		else
			(void)_snprintf(device, sizeof(device), "/dev/dri/renderD128");
	}
	return device;
}

static void libavcodec_uninit(H264_CONTEXT* h264)
{
	WINPR_ASSERT(h264);

	H264_CONTEXT_LIBAVCODEC* sys = (H264_CONTEXT_LIBAVCODEC*)h264->pSystemData;

	if (!sys)
		return;

	if (sys->packet)
	{
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(58, 133, 100)
		av_packet_unref(sys->packet);
#else
		av_packet_free(&sys->packet);
#endif
	}

	if (sys->videoFrame)
	{
#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(55, 18, 102)
		av_frame_free(&sys->videoFrame);
#else
		av_free(sys->videoFrame);
#endif
	}

#if defined(WITH_VAAPI) || defined(WITH_VAAPI_H264_ENCODING) || defined(WITH_VIDEOTOOLBOX)
	if (sys->hwVideoFrame)
	{
#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(55, 18, 102)
		av_frame_free(&sys->hwVideoFrame);
#else
		av_free(sys->hwVideoFrame);
#endif
	}

	if (sys->hwctx)
		av_buffer_unref(&sys->hwctx);

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(57, 80, 100) || defined(WITH_VIDEOTOOLBOX)

	if (sys->hw_frames_ctx)
		av_buffer_unref(&sys->hw_frames_ctx);

#endif

#endif

	if (sys->codecParser)
		av_parser_close(sys->codecParser);

	if (sys->codecDecoderContext)
	{
#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(55, 69, 100)
		avcodec_free_context(&sys->codecDecoderContext);
#else
		avcodec_close(sys->codecDecoderContext);
		av_free(sys->codecDecoderContext);
#endif
	}

	libavcodec_destroy_encoder_context(h264);
	free(sys);
	h264->pSystemData = nullptr;
}

static enum AVPixelFormat libavcodec_get_format(struct AVCodecContext* ctx,
                                                const enum AVPixelFormat* fmts)
{
	WINPR_ASSERT(ctx);

	H264_CONTEXT* h264 = (H264_CONTEXT*)ctx->opaque;
	WINPR_ASSERT(h264);

	H264_CONTEXT_LIBAVCODEC* sys = (H264_CONTEXT_LIBAVCODEC*)h264->pSystemData;
	WINPR_ASSERT(sys);

	for (const enum AVPixelFormat* p = fmts; *p != AV_PIX_FMT_NONE; p++)
	{
		if (*p == sys->hw_pix_fmt)
		{
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(57, 80, 100) || defined(WITH_VIDEOTOOLBOX)
			if (sys->hw_frames_ctx)
				av_buffer_unref(&sys->hw_frames_ctx);

			sys->hw_frames_ctx = av_hwframe_ctx_alloc(sys->hwctx);

			if (!sys->hw_frames_ctx)
			{
				return AV_PIX_FMT_NONE;
			}

			sys->codecDecoderContext->pix_fmt = *p;
			AVHWFramesContext* frames = (AVHWFramesContext*)sys->hw_frames_ctx->data;
			frames->format = *p;
			frames->height = sys->codecDecoderContext->coded_height;
			frames->width = sys->codecDecoderContext->coded_width;
#ifdef WITH_VIDEOTOOLBOX
			frames->sw_format = AV_PIX_FMT_YUV420P;
#else
			frames->sw_format =
			    (sys->codecDecoderContext->sw_pix_fmt == AV_PIX_FMT_YUV420P10 ? AV_PIX_FMT_P010
			                                                                  : AV_PIX_FMT_NV12);
#endif
			frames->initial_pool_size = 20;

			if (sys->codecDecoderContext->active_thread_type & FF_THREAD_FRAME)
				frames->initial_pool_size += sys->codecDecoderContext->thread_count;

			int err = av_hwframe_ctx_init(sys->hw_frames_ctx);

			if (err < 0)
			{
				WLog_Print(h264->log, WLOG_ERROR, "Could not init hwframes context: %s",
				           av_err2str(err));
				return AV_PIX_FMT_NONE;
			}

			sys->codecDecoderContext->hw_frames_ctx = av_buffer_ref(sys->hw_frames_ctx);
#endif
			return *p;
		}
	}

	return AV_PIX_FMT_NONE;
}

static BOOL libavcodec_init(H264_CONTEXT* h264)
{
	WINPR_ASSERT(h264);
	H264_CONTEXT_LIBAVCODEC* sys =
	    (H264_CONTEXT_LIBAVCODEC*)calloc(1, sizeof(H264_CONTEXT_LIBAVCODEC));

	if (!sys)
	{
		goto EXCEPTION;
	}

	h264->pSystemData = (void*)sys;

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(58, 10, 100)
	avcodec_register_all();
#endif

	if (!h264->Compressor)
	{
		sys->codecDecoder = avcodec_find_decoder(AV_CODEC_ID_H264);

		if (!sys->codecDecoder)
		{
			WLog_Print(h264->log, WLOG_ERROR, "Failed to find libav H.264 codec");
			goto EXCEPTION;
		}

		sys->codecDecoderContext = avcodec_alloc_context3(sys->codecDecoder);

		if (!sys->codecDecoderContext)
		{
			WLog_Print(h264->log, WLOG_ERROR, "Failed to allocate libav codec context");
			goto EXCEPTION;
		}

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(59, 18, 100)
		if (sys->codecDecoder->capabilities & AV_CODEC_CAP_TRUNCATED)
		{
			sys->codecDecoderContext->flags |= AV_CODEC_FLAG_TRUNCATED;
		}
#endif

#ifdef WITH_VAAPI

		if (!sys->hwctx)
		{
			int ret = av_hwdevice_ctx_create(&sys->hwctx, AV_HWDEVICE_TYPE_VAAPI,
			                                 get_vaapi_device(), nullptr, 0);

			if (ret < 0)
			{
				WLog_Print(h264->log, WLOG_ERROR,
				           "Could not initialize hardware decoder, falling back to software: %s",
				           av_err2str(ret));
				sys->hwctx = nullptr;
				goto fail_hwdevice_create;
			}
		}
		WLog_Print(h264->log, WLOG_INFO, "Using VAAPI for accelerated H264 decoding");

		sys->codecDecoderContext->get_format = libavcodec_get_format;
		sys->hw_pix_fmt = AV_PIX_FMT_VAAPI;
#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(57, 80, 100)
		sys->codecDecoderContext->hw_device_ctx = av_buffer_ref(sys->hwctx);
#endif
		sys->codecDecoderContext->opaque = (void*)h264;
	fail_hwdevice_create:
#endif

#ifdef WITH_VIDEOTOOLBOX

		if (!sys->hwctx)
		{
			int ret = av_hwdevice_ctx_create(&sys->hwctx, AV_HWDEVICE_TYPE_VIDEOTOOLBOX, nullptr,
			                                 nullptr, 0);

			if (ret < 0)
			{
				WLog_Print(
				    h264->log, WLOG_ERROR,
				    "Could not initialize VideoToolbox decoder, falling back to software: %s",
				    av_err2str(ret));
				sys->hwctx = nullptr;
				goto fail_vt_create;
			}
		}
		WLog_Print(h264->log, WLOG_INFO, "Using VideoToolbox for accelerated H264 decoding");

		sys->codecDecoderContext->get_format = libavcodec_get_format;
		sys->hw_pix_fmt = AV_PIX_FMT_VIDEOTOOLBOX;
		sys->codecDecoderContext->hw_device_ctx = av_buffer_ref(sys->hwctx);
		sys->codecDecoderContext->opaque = (void*)h264;
	fail_vt_create:
#endif

		if (avcodec_open2(sys->codecDecoderContext, sys->codecDecoder, nullptr) < 0)
		{
			WLog_Print(h264->log, WLOG_ERROR, "Failed to open libav codec");
			goto EXCEPTION;
		}

		sys->codecParser = av_parser_init(AV_CODEC_ID_H264);

		if (!sys->codecParser)
		{
			WLog_Print(h264->log, WLOG_ERROR, "Failed to initialize libav parser");
			goto EXCEPTION;
		}
	}
	else
	{
#ifdef WITH_VAAPI_H264_ENCODING
		if (h264->hwAccel) /* user requested hw accel */
		{
			sys->codecEncoder = avcodec_find_encoder_by_name("h264_vaapi");
			if (!sys->codecEncoder)
			{
				WLog_Print(h264->log, WLOG_ERROR, "H264 VAAPI encoder not found");
			}
			else if (av_hwdevice_ctx_create(&sys->hwctx, AV_HWDEVICE_TYPE_VAAPI, get_vaapi_device(),
			                                nullptr, 0) < 0)
			{
				WLog_Print(h264->log, WLOG_ERROR, "av_hwdevice_ctx_create failed");
				sys->codecEncoder = nullptr;
				sys->hwctx = nullptr;
			}
			else
			{
				WLog_Print(h264->log, WLOG_INFO, "Using VAAPI for accelerated H264 encoding");
			}
		}
#endif
		if (!sys->codecEncoder)
		{
			sys->codecEncoder = avcodec_find_encoder(AV_CODEC_ID_H264);
			h264->hwAccel = FALSE; /* not supported */
		}

		if (!sys->codecEncoder)
		{
			WLog_Print(h264->log, WLOG_ERROR, "Failed to initialize H264 encoder");
			goto EXCEPTION;
		}
	}

#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(55, 18, 102)
	sys->videoFrame = av_frame_alloc();
#if defined(WITH_VAAPI) || defined(WITH_VAAPI_H264_ENCODING) || defined(WITH_VIDEOTOOLBOX)
	sys->hwVideoFrame = av_frame_alloc();
#endif
#else
	sys->videoFrame = avcodec_alloc_frame();
#endif

	if (!sys->videoFrame)
	{
		WLog_Print(h264->log, WLOG_ERROR, "Failed to allocate libav frame");
		goto EXCEPTION;
	}

#if defined(WITH_VAAPI) || defined(WITH_VAAPI_H264_ENCODING) || defined(WITH_VIDEOTOOLBOX)
	if (!sys->hwVideoFrame)
	{
		WLog_Print(h264->log, WLOG_ERROR, "Failed to allocate libav hw frame");
		goto EXCEPTION;
	}

#endif
	sys->videoFrame->pts = 0;
	return TRUE;
EXCEPTION:
	libavcodec_uninit(h264);
	return FALSE;
}

void region16_init(REGION16* region)
{
	WINPR_ASSERT(region);

	const REGION16 empty = WINPR_C_ARRAY_INIT;
	*region = empty;
}

int region16_n_rects(const REGION16* region)
{
	WINPR_ASSERT(region);
	if (!region->data)
		return 0;

	return WINPR_ASSERTING_INT_CAST(int, region->data->nbRects);
}

const RECTANGLE_16* region16_rects(const REGION16* region, UINT32* nbRects)
{
	if (nbRects)
		*nbRects = 0;

	if (!region)
		return nullptr;

	REGION16_DATA* data = region->data;
	if (!data)
		return nullptr;

	if (nbRects)
		*nbRects = WINPR_ASSERTING_INT_CAST(UINT32, data->nbRects);

	return data->rects;
}

static inline RECTANGLE_16* region16_rects_noconst(REGION16* region)
{
	WINPR_ASSERT(region);

	REGION16_DATA* data = region->data;

	if (!data)
		return nullptr;

	return data->rects;
}

const RECTANGLE_16* region16_extents(const REGION16* region)
{
	if (!region)
		return nullptr;

	return &region->extents;
}

static RECTANGLE_16* region16_extents_noconst(REGION16* region)
{
	if (!region)
		return nullptr;

	return &region->extents;
}

BOOL rectangle_is_empty(const RECTANGLE_16* rect)
{
	WINPR_ASSERT(rect);

	/* A rectangle with width <= 0 or height <= 0 should be regarded
	 * as empty.
	 */
	return ((rect->left >= rect->right) || (rect->top >= rect->bottom));
}

BOOL region16_is_empty(const REGION16* region)
{
	WINPR_ASSERT(region);
	if (!region->data)
		return TRUE;
	return (region->data->nbRects == 0);
}

BOOL rectangles_equal(const RECTANGLE_16* r1, const RECTANGLE_16* r2)
{
	WINPR_ASSERT(r1);
	WINPR_ASSERT(r2);

	return ((r1->left == r2->left) && (r1->top == r2->top) && (r1->right == r2->right) &&
	        (r1->bottom == r2->bottom));
}

BOOL rectangles_intersects(const RECTANGLE_16* r1, const RECTANGLE_16* r2)
{
	RECTANGLE_16 tmp = WINPR_C_ARRAY_INIT;
	return rectangles_intersection(r1, r2, &tmp);
}

BOOL rectangles_intersection(const RECTANGLE_16* r1, const RECTANGLE_16* r2, RECTANGLE_16* dst)
{
	WINPR_ASSERT(r1);
	WINPR_ASSERT(r2);
	WINPR_ASSERT(dst);

	dst->left = MAX(r1->left, r2->left);
	dst->right = MIN(r1->right, r2->right);
	dst->top = MAX(r1->top, r2->top);
	dst->bottom = MIN(r1->bottom, r2->bottom);
	return (dst->left < dst->right) && (dst->top < dst->bottom);
}

const char* rectangle_to_string(const RECTANGLE_16* rect, char* buffer, size_t length)
{
	if (!buffer || (length < 2))
		return nullptr;
	if (!rect)
		(void)_snprintf(buffer, length - 1, "{ nullptr }");
	else
		(void)_snprintf(buffer, length - 1, "{%" PRIu16 "x%" PRIu16 "-%" PRIu16 "x%" PRIu16 "}",
		                rect->left, rect->top, rect->right, rect->bottom);
	return buffer;
}

RECTANGLE_16* rectangles_clone(const RECTANGLE_16* rects, size_t count)
{
	if (count == 0)
		return nullptr;
	if (count > SIZE_MAX / sizeof(RECTANGLE_16))
		return nullptr;

	WINPR_ASSERT(rects);

	RECTANGLE_16* clone = calloc(count, sizeof(RECTANGLE_16));
	if (!clone)
		return nullptr;

	memcpy(clone, rects, sizeof(RECTANGLE_16) * count);
	return clone;
}

static void freeRegion(REGION16_DATA* data)
{
	if (data)
		free(data->rects);
	free(data);
}

void region16_clear(REGION16* region)
{
	WINPR_ASSERT(region);

	freeRegion(region->data);
	region->data = nullptr;

	const RECTANGLE_16 empty = WINPR_C_ARRAY_INIT;
	region->extents = empty;
}

WINPR_ATTR_NODISCARD
static REGION16_DATA* allocateRegion(size_t nbItems)
{
	REGION16_DATA* data = calloc(1, sizeof(REGION16_DATA));
	if (!data)
		return nullptr;

	if (nbItems > 0)
	{
		data->rects = calloc(nbItems, sizeof(RECTANGLE_16));
		if (!data->rects)
		{
			free(data);
			return nullptr;
		}
	}

	data->nbRects = nbItems;
	return data;
}

static inline RECTANGLE_16* nextRect(REGION16_DATA* data, size_t index)
{
	WINPR_ASSERT(data);
	if (index + 1 > data->nbRects)
	{
		RECTANGLE_16* rects = realloc(data->rects, (index + 1) * sizeof(RECTANGLE_16));
		if (!rects)
		{
			freeRegion(data);
			return nullptr;
		}

		const RECTANGLE_16 empty = WINPR_C_ARRAY_INIT;
		rects[index] = empty;
		data->nbRects = index + 1;
		data->rects = rects;
	}
	return &data->rects[index];
}

static BOOL resizeRegion(REGION16* region, size_t nbItems)
{
	WINPR_ASSERT(region);
	if (nbItems == 0)
	{
		freeRegion(region->data);
		region->data = nullptr;
		return TRUE;
	}

	if (!region->data)
	{
		region->data = allocateRegion(nbItems);
		return region->data != nullptr;
	}

	RECTANGLE_16* rects = realloc(region->data->rects, nbItems * sizeof(RECTANGLE_16));
	if (!rects)
	{
		free(region->data->rects);
		region->data->nbRects = 0;
		region->data->rects = nullptr;
		return FALSE;
	}

	for (size_t x = region->data->nbRects; x < nbItems; x++)
	{
		const RECTANGLE_16 empty = WINPR_C_ARRAY_INIT;
		rects[x] = empty;
	}
	region->data->rects = rects;
	region->data->nbRects = nbItems;
	return TRUE;
}

static inline BOOL region16_copy_data(REGION16* dst, const REGION16* src)
{
	WINPR_ASSERT(dst);
	WINPR_ASSERT(src);

	freeRegion(dst->data);
	dst->data = nullptr;

	if (src->data && (src->data->nbRects > 0))
	{
		dst->data = allocateRegion(src->data->nbRects);
		if (!dst->data || !dst->data->rects)
			return FALSE;
		memcpy(dst->data->rects, src->data->rects, dst->data->nbRects * sizeof(RECTANGLE_16));
	}
	return TRUE;
}

BOOL region16_copy(REGION16* dst, const REGION16* src)
{
	if (dst == src)
		return TRUE;

	WINPR_ASSERT(dst);
	WINPR_ASSERT(src);

	dst->extents = src->extents;

	return region16_copy_data(dst, src);
}

void region16_print(const REGION16* region)
{
	UINT32 nbRects = 0;
	int currentBandY = -1;
	const RECTANGLE_16* rects = region16_rects(region, &nbRects);

	WLog_DBG(TAG, "nrects=%" PRIu32 "", nbRects);

	for (UINT32 i = 0; i < nbRects; i++)
	{
		const RECTANGLE_16* rect = &rects[i];

		if (rect->top != currentBandY)
		{
			currentBandY = rect->top;
			WLog_DBG(TAG, "band %d: ", currentBandY);
		}

		WLog_DBG(TAG, "(%" PRIu16 ",%" PRIu16 "-%" PRIu16 ",%" PRIu16 ")", rect->left, rect->top,
		         rect->right, rect->bottom);
	}
}

static BOOL region16_copy_band_with_union(REGION16_DATA* region, const RECTANGLE_16* src,
                                          const RECTANGLE_16* end, UINT16 newTop, UINT16 newBottom,
                                          const RECTANGLE_16* unionRect, UINT32* dstCounter,
                                          const RECTANGLE_16** srcPtr)
{
	WINPR_ASSERT(region);
	WINPR_ASSERT(src);
	WINPR_ASSERT(end);
	WINPR_ASSERT(dstCounter);

	UINT16 refY = src->top;

	/* merges a band with the given rect
	 * Input:
	 *                   unionRect
	 *               |               |
	 *               |               |
	 * ==============+===============+================================
	 *   |Item1|  |Item2| |Item3|  |Item4|    |Item5|            Band
	 * ==============+===============+================================
	 *    before     |    overlap    |          after
	 *
	 * Resulting band:
	 *   +-----+  +----------------------+    +-----+
	 *   |Item1|  |      Item2           |    |Item3|
	 *   +-----+  +----------------------+    +-----+
	 *
	 *  We first copy as-is items that are before Item2, the first overlapping
	 *  item.
	 *  Then we find the last one that overlap unionRect to aggregate Item2, Item3
	 *  and Item4 to create Item2.
	 *  Finally Item5 is copied as Item3.
	 *
	 *  When no unionRect is provided, we skip the two first steps to just copy items
	 */

	if (unionRect)
	{
		/* items before unionRect */
		while ((src < end) && (src->top == refY) && (src->right < unionRect->left))
		{
			RECTANGLE_16* dst = nextRect(region, (*dstCounter)++);
			if (!dst)
				return FALSE;
			dst->top = newTop;
			dst->bottom = newBottom;
			dst->right = src->right;
			dst->left = src->left;
			src++;
		}

		/* treat items overlapping with unionRect */
		const RECTANGLE_16* startOverlap = unionRect;
		const RECTANGLE_16* endOverlap = unionRect;

		if ((src < end) && (src->top == refY) && (src->left < unionRect->left))
			startOverlap = src;

		while ((src < end) && (src->top == refY) && (src->right < unionRect->right))
		{
			src++;
		}

		if ((src < end) && (src->top == refY) && (src->left < unionRect->right))
		{
			endOverlap = src;
			src++;
		}

		{
			RECTANGLE_16* dst = nextRect(region, (*dstCounter)++);
			if (!dst)
				return FALSE;
			dst->bottom = newBottom;
			dst->top = newTop;
			dst->left = startOverlap->left;
			dst->right = endOverlap->right;
		}
	}

	/* treat remaining items on the same band */
	while ((src < end) && (src->top == refY))
	{
		RECTANGLE_16* dst = nextRect(region, (*dstCounter)++);
		if (!dst)
			return FALSE;

		dst->top = newTop;
		dst->bottom = newBottom;
		dst->right = src->right;
		dst->left = src->left;
		src++;
	}

	if (srcPtr)
		*srcPtr = src;

	return TRUE;
}

static RECTANGLE_16* next_band(RECTANGLE_16* band1, RECTANGLE_16* endPtr, int* nbItems)
{
	WINPR_ASSERT(band1);
	WINPR_ASSERT(endPtr);
	WINPR_ASSERT(nbItems);

	UINT16 refY = band1->top;
	*nbItems = 0;

	while ((band1 < endPtr) && (band1->top == refY))
	{
		band1++;
		*nbItems += 1;
	}

	return band1;
}

static BOOL band_match(const RECTANGLE_16* band1, const RECTANGLE_16* band2,
                       const RECTANGLE_16* endPtr)
{
	int refBand2 = band2->top;
	const RECTANGLE_16* band2Start = band2;

	while ((band1 < band2Start) && (band2 < endPtr) && (band2->top == refBand2))
	{
		if ((band1->left != band2->left) || (band1->right != band2->right))
			return FALSE;

		band1++;
		band2++;
	}

	if (band1 != band2Start)
		return FALSE;

	return (band2 == endPtr) || (band2->top != refBand2);
}

static BOOL rectangle_contained_in_band(const RECTANGLE_16* band, const RECTANGLE_16* endPtr,
                                        const RECTANGLE_16* rect)
{
	WINPR_ASSERT(band);
	WINPR_ASSERT(endPtr);
	WINPR_ASSERT(rect);

	UINT16 refY = band->top;

	if ((band->top > rect->top) || (rect->bottom > band->bottom))
		return FALSE;

	/* note: as the band is sorted from left to right, once we've seen an item
	 * 		that is after rect->left we're sure that the result is False.
	 */
	while ((band < endPtr) && (band->top == refY) && (band->left <= rect->left))
	{
		if (rect->right <= band->right)
			return TRUE;

		band++;
	}

	return FALSE;
}

static void free_string(char** current, BOOL cleanup)
{
	if (cleanup)
	{
		if (*current)
			memset(*current, 0, strlen(*current));
		free(*current);
		(*current) = nullptr;
	}
}

static BOOL alloc_empty_string(char** current, const char* next, size_t next_len)
{
	if (!next && (next_len > 0))
	{
		*current = calloc(next_len, 1);
		return (*current != nullptr);
	}
	return FALSE;
}

static BOOL update_string_copy_(char** current, const char* next, size_t next_len, BOOL cleanup)
{
	free_string(current, cleanup);

	if (alloc_empty_string(current, next, next_len))
		return TRUE;

	*current = (next ? strndup(next, next_len) : nullptr);
	return !next || (*current != nullptr);
}

static BOOL update_string_(char** current, char* next, size_t next_len)
{
	free_string(current, TRUE);

	if (alloc_empty_string(current, next, next_len))
		return TRUE;

	*current = next;
	return !next || (*current != nullptr);
}

